mapper.sql:
WITH baseline_ranked AS (
    SELECT ds.*,
        COALESCE(NULLIF(ds.parent_asin, ''), ds.asin) AS product_key,
        ROW_NUMBER() OVER (
            PARTITION BY ds.marketplace, ds.seller_name, COALESCE(NULLIF(ds.parent_asin, ''), ds.asin)
            ORDER BY
                CASE WHEN ds.bsr IS NULL OR ds.bsr <= 0 THEN 999999999 ELSE ds.bsr END ASC,
                ds.created_at DESC, ds.id DESC
        ) AS rn
    FROM shop_products ds
    WHERE ds.title IS NOT NULL AND ds.asin IS NOT NULL
      AND ds.marketplace = #{marketplace}
      AND ds.seller_name = #{sellerName}
      AND ds.source_run_id = #{baselineRunId}
), compare_ranked AS (
    SELECT ds.*,
        COALESCE(NULLIF(ds.parent_asin, ''), ds.asin) AS product_key,
        ROW_NUMBER() OVER (
            PARTITION BY ds.marketplace, ds.seller_name, COALESCE(NULLIF(ds.parent_asin, ''), ds.asin)
            ORDER BY
                CASE WHEN ds.bsr IS NULL OR ds.bsr <= 0 THEN 999999999 ELSE ds.bsr END ASC,
                ds.created_at DESC, ds.id DESC
        ) AS rn
    FROM shop_products ds
    WHERE ds.title IS NOT NULL AND ds.asin IS NOT NULL
      AND ds.marketplace = #{marketplace}
      AND ds.seller_name = #{sellerName}
      AND ds.source_run_id = #{compareRunId}
), b AS (
    SELECT * FROM baseline_ranked WHERE rn = 1
), c AS (
    SELECT * FROM compare_ranked WHERE rn = 1
)

